        glassBreak() { if (!this.mp3('glass_break')) { this.tone(760, 'sine', 0.16, 0.18, 220); this.tone(1800, 'triangle', 0.1, 0.12, 900); } }
        spikeHit() { if (!this.mp3('spike_hit')) this.hurt(); }
        bossIntro() { if (!this.mp3('boss_intro')) { this.tone(180, 'sawtooth', 0.35, 0.14, 60); this.danger(); } }
        bossPhase() { if (!this.mp3('boss_phase')) { this.tone(140, 'sawtooth', 0.3, 0.15, 60); setTimeout(() => this.tone(200, 'sawtooth', 0.24, 0.14, 90), 180); } }
        bossDefeat() { if (!this.mp3('boss_defeat')) { this.tone(1046, 'square', 0.2, 0.16, 1568); setTimeout(() => this.tone(1318, 'square', 0.24, 0.16, 1976), 160); } }
