      function addParticles(x, y, col, count = 10, spd = 130) {
        for (let i = 0; i < count; i++) {
          const a = Math.random() * Math.PI * 2;
          const v = (0.3 + Math.random() * 0.7) * spd;
          game.particles.push({
            x, y, vx: Math.cos(a) * v, vy: Math.sin(a) * v - 25,
            sz: 3 + ((Math.random() * 3) | 0), col, life: 0.4 + Math.random() * 0.3
          });
        }
      }

      /* v5.10 B3: 추락 딥 오버레이 (DOM이라 게임 리셋에 안 지워짐) */
