      function applyTouchLayout() {
        const bL = document.getElementById('touchBtnLeft');
        const bR = document.getElementById('touchBtnRight');
        const bJ = document.getElementById('touchBtnJump');
        if (!bL || !bR || !bJ) return;

        const s = ctrl.scale / 100;
        const ox = Number(ctrl.offsetX) || 0;
        const oy = Number(ctrl.offsetY) || 0;
        const bot = 14 + oy;

        [bL, bR, bJ].forEach((b) => {
          b.style.left = '';
          b.style.right = '';
          b.style.bottom = `${bot}px`;
          b.style.transform = `scale(${s})`;
        });

        if (ctrl.preset === 'split') {
          bL.style.left = `${Math.max(6, 14 + ox)}px`;
          bL.style.transformOrigin = 'bottom left';
          bR.style.left = `${Math.max(74, Math.round(106 * s) + 18 + ox)}px`;
          bR.style.transformOrigin = 'bottom left';
          bJ.style.right = `${Math.max(6, 14 - ox)}px`;
          bJ.style.transformOrigin = 'bottom right';
        } else if (ctrl.preset === 'left') {
          bL.style.left = `${Math.max(6, 14 + ox)}px`;
          bL.style.transformOrigin = 'bottom left';
          bR.style.left = `${Math.max(72, Math.round(102 * s) + 16 + ox)}px`;
          bR.style.transformOrigin = 'bottom left';
          bJ.style.left = `${Math.max(142, Math.round(204 * s) + 22 + ox)}px`;
          bJ.style.transformOrigin = 'bottom left';
        } else {
          bJ.style.right = `${Math.max(6, 14 - ox)}px`;
          bJ.style.transformOrigin = 'bottom right';
          bR.style.right = `${Math.max(84, Math.round(116 * s) + 18 - ox)}px`;
          bR.style.transformOrigin = 'bottom right';
          bL.style.right = `${Math.max(158, Math.round(216 * s) + 24 - ox)}px`;
          bL.style.transformOrigin = 'bottom right';
        }

        document.getElementById('lblOffsetX').textContent = `${ox} px`;
        document.getElementById('lblOffsetY').textContent = `${oy} px`;
        document.getElementById('lblBtnScale').textContent = `${ctrl.scale}%`;
        document.getElementById('rngOffsetX').value = ox;
        document.getElementById('rngOffsetY').value = oy;
        document.getElementById('rngBtnScale').value = ctrl.scale;

        document.querySelectorAll('.preset-btn').forEach((btn) => {
          const active = btn.getAttribute('data-preset') === ctrl.preset;
          btn.className = 'preset-btn py-2.5 px-2 font-bold text-xs sm:text-sm border-2 cursor-pointer ' +
            (active ? 'border-sky-400 bg-sky-900/70 text-white' : 'border-slate-700 bg-slate-900 text-slate-300');
        });
      }

