      const modes = ['normal', 'classic', 'timeattack', 'lava', 'zombie', 'relay', 'chain', 'bomb', 'boss'];
      let map = maps[(Math.random() * maps.length) | 0];
      let mode = modes[(Math.random() * modes.length) | 0];
      const patch = { map, mode };
      if (mode === 'classic') { patch.originPct = 3; patch.originRandom = false; patch.items = false; patch.buffs = false; patch.traps = false; }
      applyRules(patch, (MP().byId(map).name) + ' · ' + MD().modeById(mode).name);
