      const S = V.st();
      if (!S) return;
      if (m.pid) {
        M.infected[m.pid] = true;
        if (m.pid !== S.me.pid) V.toast('🧟 ' + (m.nick || '참가자') + ' 감염!', 'danger', '이제 생존자를 쫓습니다', 2400);
      }
      if (m.to && m.to === S.me.pid && !M.infected[S.me.pid]) infectMe('player');
