  /* ================================================================
     월드 드로잉 (좀비·불꽃·발자국)
     ================================================================ */
  V.onDrawFx = function (ctx, camY, lh) {
    const mode = curMode();
    const g = J() && J().game;
    if (!g) return;
    if (mode === 'zombie') {
      M.zombs.forEach((z) => {
        const sy = z.y - camY;
        if (sy < -70 || sy > lh + 70) return;
        drawZombieWorld(ctx, camY, z.x, z.y, z.facing || 1, 1);
        /* v4.5: 머리 위 추격 상태 표시 */
        if (z.chasing) {
          ctx.save();
          ctx.font = 'bold 10px "Galmuri11", monospace';
          ctx.textAlign = 'center';
          const bob = Math.sin((J().game.time || 0) * 6) * 1.5;
          ctx.fillStyle = 'rgba(8,4,12,.7)';
          const tw = ctx.measureText('🧟 추격 중!').width + 10;
          ctx.fillRect(z.x + 12 - tw / 2, sy - 52 + bob, tw, 15);
          ctx.strokeStyle = 'rgba(248,113,113,.85)'; ctx.lineWidth = 1;
          ctx.strokeRect(z.x + 12 - tw / 2, sy - 52 + bob, tw, 15);
          ctx.fillStyle = '#fecaca';
          ctx.fillText('🧟 추격 중!', z.x + 12, sy - 41 + bob);
          ctx.restore();
        }
      });
      /* 감염된 참가자도 좀비로 보이게 */
      const S = V.st();
      if (S && S.peers) {
        S.peers.forEach((pr) => {
          if (!M.infected[pr.pid] || pr.stale) return;
          const sy = pr.ry - camY;
          if (sy < -70 || sy > lh + 70) return;
          drawZombieWorld(ctx, camY, pr.rx, pr.ry, 1, 0.92);
        });
      }
    }
    if (mode === 'burning') {
      const plats = J().platforms || [];
      plats.forEach((p) => {
        if (!p._burnT || p._burnT <= 0 || p.crumbled || p.index <= 0) return;
        const sy = p.y - camY;
        if (sy < -40 || sy > lh + 40) return;
        const k = Math.min(1, (3 - p._burnT) / 3);
        for (let i = 0; i < 3 + (k * 6 | 0); i++) {
          const fx = p.x + 4 + ((i * 17) % Math.max(6, p.w - 8));
          const fh = 6 + ((i * 7 + (g.time * 40 | 0)) % 10);
          ctx.fillStyle = i % 3 === 0 ? '#fbbf24' : (i % 3 === 1 ? '#f97316' : '#ef4444');
          ctx.fillRect(fx, sy - fh, 4, fh);
        }
        ctx.fillStyle = 'rgba(239,68,68,.22)';
        ctx.fillRect(p.x - 2, sy - 2, p.w + 4, p.h + 4);
      });
    }
    /* 발자국 */
    if (V.QOL.footprints && g.inPlay) {
      const pl = J().player;
      if (pl.onGround && pl.plat) {
        if (!M.footT || (g.time || 0) - M.footT > 0.28) {
          M.footT = g.time || 0;
          M.foot = M.foot || [];
          M.foot.push({ x: pl.x + (pl.facing > 0 ? 4 : 22), y: pl.y + pl.h - 2, t: g.time || 0, f: pl.facing });
          if (M.foot.length > 40) M.foot.shift();
        }
      }
      (M.foot || []).forEach((f) => {
        const sy = f.y - camY;
        if (sy < -20 || sy > lh + 20) return;
        ctx.fillStyle = 'rgba(15,23,42,.32)';
        ctx.fillRect(f.x, sy, 3, 2);
      });
    }
  };

