      btn.innerHTML = '<span>🛠️ 개발자 명령</span><span style="font-size:9px;color:#c4b5fd">/top · /god · /fly · /skip · /unlockall · /bossskip</span>';
      var anchor = $('btnOpenSettingsPause') || card.firstChild;
