    if ($('v43GhostPause')) return;
    var card = pm.querySelector('.flex.flex-col.gap-2\\.5') || pm.querySelector('.pixel-panel');
    if (!card) return;
    var btn = doc.createElement('button');
    btn.type = 'button';
    btn.id = 'v43GhostPause';
    var on = !!(V.ghostOn && V.ghostOn());
    btn.className = on ? 'on' : '';
    btn.innerHTML = '<span>👻 고스트: <b class="v43-gs">' + (on ? 'ON' : 'OFF') + '</b></span><span style="font-size:9px;color:#a5b4fc">내 최고 기록과 함께 달리기</span>';
    var anchor = $('btnOpenSettingsPause') || card.firstChild;
    card.insertBefore(btn, anchor);
