    R(c, x - 36 * s, y - 138 * s, 72 * s, 54 * s, 'rgba(56,189,248,.55)');
    R(c, x - 36 * s, y - 76 * s, 72 * s, 18 * s, 'rgba(232,121,249,.6)');
    CIR(c, x - 20 * s, y - 34 * s, 8 * s, 'rgba(248,113,113,.9)');
    CIR(c, x + 4 * s, y - 34 * s, 8 * s, 'rgba(250,204,21,.9)');
