    SL(c, [[x + 10 * s, y - 150 * s], [x + 70 * s, y - 240 * s], [x + 130 * s, y - 150 * s]], 'rgba(34,26,48,.98)');
    R(c, x - 4 * s, y - 268 * s, 6 * s, 30 * s, 'rgba(34,26,48,.98)');
