      for (let i = 8; i < w - 4; i += 14) { c.beginPath(); c.moveTo(x + i, y + 6); c.quadraticCurveTo(x + i + 4, y + h / 2, x + i, y + h - 2); c.stroke(); }
      c.fillStyle = 'rgba(148,163,184,.55)';
