      ctx.beginPath(); ctx.arc(0, -9 + bob, 7, 0, 6.3); ctx.fill();
      ctx.beginPath(); ctx.moveTo(-7, -12 + bob); ctx.lineTo(-4, -18 + bob); ctx.lineTo(-1, -12 + bob); ctx.fill();
      ctx.beginPath(); ctx.moveTo(7, -12 + bob); ctx.lineTo(4, -18 + bob); ctx.lineTo(1, -12 + bob); ctx.fill();
      ctx.fillStyle = '#1f2937'; ctx.fillRect(-3, -10 + bob, 2, 2); ctx.fillRect(1, -10 + bob, 2, 2);
      ctx.strokeStyle = spec.col; ctx.lineWidth = 2; ctx.beginPath(); ctx.moveTo(7, -2 + bob); ctx.quadraticCurveTo(13, -6 + bob, 9, -12 + bob); ctx.stroke();
