  function trackRoom() {
    const S = V.st();
    if (!S || !S.room) return;
    const code = S.room.code;
    if (!code || code === QS.lastCode) return;
    QS.lastCode = code;
    QS.rooms = (QS.rooms || []).filter((r) => r.code !== code);
    QS.rooms.unshift({ code: code, map: S.room.map, mode: S.room.mode, ts: Date.now() });
    QS.rooms = QS.rooms.slice(0, 3);
    V.lsSet('jw44_rooms_v1', QS.rooms);
    renderRooms();
  }
