  /* ================================================================
     16) 연습장: 착지점 점선 미리보기 + 층수 자동 저장
     ================================================================ */
  function practiceKey() { return 'p_' + ((MP() && MP().current) || 'default'); }
  function savePracticeFloor() {
    if (!Q.practiceSave) return;
    const p = J() && J().player;
    if (!p || !p.plat) return;
    const t = performance.now();
    if (t - QS.lastPracticeSave < 1500) return;
    QS.lastPracticeSave = t;
    const key = practiceKey();
    if (QS.practice[key] === p.plat.index) return;   /* v5.13-perf: 층이 그대로면 저장하지 않는다 */
    QS.practice[key] = p.plat.index;
    V.lsSet('jw44_practice_v1', QS.practice);
  }
  G.resumePractice = function () {
    const idx = QS.practice[practiceKey()] || 0;
    if (!idx) { V.toast('연습장 기록 없음', 'danger', '연습 모드로 몇 층 올라가 보세요', 1800); return; }
    const p = J() && J().player;
    const t = ((J() && J().platforms) || []).find((q) => q.index === idx);
    if (!p || !t) return;
    p.x = t.x + t.w / 2 - p.w / 2; p.y = t.y - p.h - 1;
    p.vx = 0; p.vy = 0; p.onGround = true; p.plat = t;
    J().game.camY = p.y - 240;
    V.toast('🎯 연습장 이어서', 'lucky', idx + '층부터', 2000);
  };

  /* 연습장 착지 점선: 현재 충전 세기로 예상 착지점까지 */
  function drawPractice(ctx, camY, lh) {
    if (!V.QOL.practice) return;
    const p = J() && J().player, g = J() && J().game;
    if (!p || !g || !g.inPlay || !p.charging) return;
    const pwr = Math.max(0.12, p.charge);
    const jp = (V.api().jumpPower && V.api().jumpPower()) || 1;
    const vy0 = -(360 + pwr * 605) * jp;
    const dir = (J().keys && J().keys.left) ? -1 : (J().keys && J().keys.right ? 1 : (p.aimDir || 0));
    const vx0 = dir * (145 + pwr * 260);
    const grav = (J().gravity && J().gravity()) || 1380;
    let x = p.x + 14, y = p.y + 17, vy = vy0;
    const dt = 1 / 60;
    const plats2 = (J() && J().platforms) || [];
    let hit = null;
    for (let i = 0; i < 150; i++) {
      vy += grav * dt; x += vx0 * dt; y += vy * dt;
      if (i % 4 === 0) {
        const sy = y - camY;
        if (sy > -20 && sy < lh + 20) {
          ctx.fillStyle = 'rgba(253,224,71,.55)';
          ctx.fillRect((x | 0) - 1, (sy | 0) - 1, 2, 2);
        }
      }
      if (vy > 0) {
        for (let k = 0; k < plats2.length; k++) {
          const q = plats2[k];
          if (q.crumbled || q.index < 0) continue;
          if (x > q.x && x < q.x + q.w && y >= q.y && y < q.y + 14) { hit = q; break; }
        }
      }
      if (hit) break;
      if (y - camY > lh + 60) break;
    }
    if (hit) {
      const sy = hit.y - camY;
      ctx.strokeStyle = '#fde047';
      ctx.setLineDash([3, 3]);
      ctx.beginPath();
      ctx.moveTo(hit.x, sy);
      ctx.lineTo(hit.x + hit.w, sy);
      ctx.stroke();
      ctx.setLineDash([]);
      ctx.fillStyle = 'rgba(253,224,71,.9)';
      ctx.fillRect((x | 0) - 2, (sy | 0) - 12, 4, 10);
    }
  }
  G.drawPractice = drawPractice;

  /* ================================================================
     17) 친구 접속/초대 알림음 + 마지막 접속일
     ================================================================ */
  function friendTick() {
    const S = V.st();
    if (!S || !S.presence) return;
    const now = Date.now();
    Object.keys(S.presence).forEach((ftag) => {
      const a = S.presence[ftag] || {};
      const fresh = now - (a.ts || 0) < 60000;
      const was = QS.online[ftag];
      if (fresh && was === false && Q.friendSound) {
        V.beep(1180, 0.1, 0.1, 'square', 1560);
        V.toast('🔔 친구 접속', 'chat', (a.nick || '친구') + ' 님이 접속했습니다', 2200);
      }
      QS.online[ftag] = fresh;
      if (fresh) QS.seen[ftag] = { at: now, nick: a.nick };
      else if (!QS.seen[ftag]) QS.seen[ftag] = { at: a.ts || now, nick: a.nick };
    });
    if (now - (QS.seenSaveT || 0) > 5000) { QS.seenSaveT = now; V.lsSet('jw44_seen_v1', QS.seen); }
  }
  function renderFriendPanel() {
    const box = $('v44FriendBody');
    if (!box) return;
    const S = V.st();
    const friends = V.lsGet('jw_friends_v1', []) || [];
    box.innerHTML = '<div class="v42-row"><span class="v42-lbl">🔔 접속 알림음</span>' +
      '<button type="button" class="v42-chip ' + (Q.friendSound ? 'green on' : '') + '" data-ftog="1">' + (Q.friendSound ? 'ON' : 'OFF') + '</button></div>' +
      (friends.length ? friends.map((f) => {
        const a = (S && S.presence && S.presence[f.ftag]) || {};
        const live = Date.now() - (a.ts || 0) < 60000;
        const seen = QS.seen[f.ftag];
        const when = live ? '🟢 접속 중' : (seen ? '⚫ 마지막 접속 ' + new Date(seen.at).toLocaleString('ko-KR', { month: 'numeric', day: 'numeric', hour: '2-digit', minute: '2-digit' }) : '⚫ 기록 없음');
        return '<div class="v43-frow"><span class="nm">' + esc(f.nick) + '</span><span class="st ' + (live ? 'ok' : '') + '">' + when + '</span></div>';
      }).join('') : '<div class="v43-empty">친구가 없습니다 · 친구 탭에서 추가하세요</div>');
    box.querySelectorAll('[data-ftog]').forEach((b) => b.addEventListener('click', () => {
      Q.friendSound = !Q.friendSound; G.saveQ44(); renderFriendPanel();
      V.toast(Q.friendSound ? '🔔 알림음 ON' : '🔕 알림음 OFF', 'chat', null, 1400);
    }));
  }
  G.renderFriendPanel = renderFriendPanel;

  /* ================================================================
     18) 신기록 완주 시 자동 인증 카드
     ================================================================ */
  function autoCard(clear, prevBest, prevT) {
    if (!Q.autoCard || !clear) return;
    /* v5.28: 스토리 판 클리어에서는 자동 카드를 띄우지 않는다 — 카드가 결과창의 [다음 스테이지 ▶]을 가려서
       원터치 진행이 막했다. 카드는 결과창의 🖼️ 인증샷 카드 버튼으로 그대로 만들 수 있다. */
    try {
      var _sr528 = V.storyRun;
      if (_sr528 && _sr528.mapId === (((MP() && MP().current) || 'default')) && _sr528.mode === MD().rules.mode) return;
    } catch (e) {}
    /* v4.8.5: 완주는 높이가 늘 정상이라 매번 '신기록'으로 카드가 떴다 → 첫 완주이거나 최단 시간 갱신일 때만 */
    let tNow = 0;
    try { tNow = Math.round(((MD() && MD().lastSoloEnd && MD().lastSoloEnd.time) || 0) * 1000); } catch (e) {}
    const isNew = !prevT || (tNow > 0 && tNow < prevT);
    if (!isNew) return;
    setTimeout(() => {
      const btn = $('soloEndCard');
      if (btn) { try { btn.click(); } catch (e) {} }
      else {
        const mb = $('mpResultCardBtn');
        if (mb) { try { mb.click(); } catch (e) {} }
      }
    }, 1100);
  }
  G.autoCard = autoCard;

