      const t = hash(i * 13.3 + seed);
      const bw = 22 + t * 36;
      const x = (i / count) * (W + 60) - 30 + hash(i * 5 + seed) * 12;
      const bh = 60 + hash(i * 7.7 + seed * 2) * 240;
