      let y = top + base * span + Math.sin(t * (m.spd || 0.5) + i) * (m.wob || 16);
      const x = ((hash(i * 4.7 + (m.seed || 3)) * (W + 60) - 30) + Math.sin(t * (m.spd || 0.5) * 0.7 + i * 2.1) * (m.wob || 16)) % (W + 60);
