      const yb = Y(G, uBase), yt = Y(G, uTop);
      if (!(inView(yb, view, 120) || inView(yt, view, 120) || (yb > view.b && yt < view.t))) return;
      const iron = 'rgba(74,58,86,.92)', iron2 = 'rgba(120,96,124,.75)', light = 'rgba(255,196,120,.30)';
