  function hills(c, G, d, view) {
    if (!d.land) return;
    const N = 16;
    for (let k = N; k >= 0; k--) {
      const u = 0.02 + (k / N) * 0.99;
      const y = Y(G, u);
      if (!inView(y, view, 520)) continue;
      const a = 0.62 - (k / N) * 0.40;
      const amp = 0.0065 + ((k * 7) % 4) * 0.0035;
      const freq = 0.0022 + ((k * 5) % 5) * 0.0008;
      ridge(c, G, u, amp, 0.0026 + (k % 3) * 0.0012, 2.3 + k * 3.7, hexA(d.land, a * 0.60), 20, 360);
      ridge(c, G, u + 0.010, amp * 1.25, 0.0019 + (k % 4) * 0.0014, 7.1 + k * 2.3, hexA(d.land, a), 20, 440,
        (k < 10 ? 'rgba(210,228,255,.055)' : null));
      /* 능선 위 수목 띠 (가까운 산에만) */
      if (d.trees !== false && k < 9 && k % 2 === 0) {
        const uu = u + 0.010;
        for (let i = 0; i < 9; i++) {
          const x = i * 62 + hash(i * 3.3 + k) * 30 - 12;
          const nzv = nz(x * (0.0019 + (k % 4) * 0.0014), 7.1 + k * 2.3);
          const ty = Y(G, uu) - (nzv * 0.5 + 0.5) * amp * 1.25 * G.h;
          if (!inView(ty, view, 60)) continue;
          const th = 16 + hash(i * 5.1 + k) * 16;
          poly(c, [[x, ty - th], [x - th * 0.34, ty + 4], [x + th * 0.34, ty + 4]], hexA(d.land, Math.min(0.85, a * 2.1)));
        }
      }
    }
  }
