  /* 지도 높이(정상 y) 알아내기: 실제 발판을 한 번만 만들어 재고 캐시 */
  function geoFor(id, useCurrent) {
    const K = (root.JWMap && root.JWMap.current) || '';
    if (_geo[id] && (!useCurrent || K !== id || _geo[id].cur)) return _geo[id];
    let top = null;
    try {
      if (useCurrent && K === id) {
        const ps = (root.__jwg && root.__jwg.platforms) || [];
        for (let i = 0; i < ps.length; i++) {
          const q = ps[i];
          if (!q || q.index <= 0) continue;
          if (top === null || q.y < top) top = q.y;
        }
      }
    } catch (e) {}
    if (top === null) {
      try {
        const M = root.JWMap;
        if (M && M.build) {
          const arr = [], ab = [];
          M.build(id, arr, ab);
          for (let i = 0; i < arr.length; i++) {
            const q = arr[i];
            if (!q || q.index <= 0) continue;
            if (top === null || q.y < top) top = q.y;
          }
        }
      } catch (e) { top = null; }
    }
    if (top === null || !isFinite(top)) {
      let total = 88;
      try { total = (root.JWMap43 && root.JWMap43.total(id)) || (root.JWMap && root.JWMap.byId && root.JWMap.byId(id) && root.JWMap.byId(id).total) || 88; } catch (e) {}
      top = -110 * total;
    }
    const g = { top: top - 150, bot: BOT, h: Math.max(1200, BOT - (top - 150)), cur: (useCurrent && K === id) };
    _geo[id] = g;
    return g;
  }

