      'body.v46-norestart #v44FastRestart{display:none!important;}',
      /* 아레나 배너: 발판을 가리지 않는 초소형 1줄 */
      '#v45Arena{top:calc(env(safe-area-inset-top,0px) + 6px)!important;width:auto!important;max-width:min(62vw,300px)!important;',
      '  padding:3px 9px!important;border-radius:999px!important;display:flex!important;align-items:center!important;gap:7px!important;',
      '  font-size:10px!important;line-height:1.2!important;background:linear-gradient(180deg,rgba(10,15,28,.72),rgba(8,12,24,.62))!important;}',
      '#v45Arena .v45a-top{display:flex!important;align-items:center!important;gap:6px!important;justify-content:flex-start!important;}',
