      '.v46team{display:inline-block;margin-left:4px;padding:0 4px;border-radius:5px;font-size:8.5px;font-weight:900;}',
      '.v46team.a{background:rgba(56,189,248,.22);color:#bae6fd;border:1px solid rgba(56,189,248,.6);}',
      '.v46team.b{background:rgba(248,113,113,.2);color:#fecaca;border:1px solid rgba(248,113,113,.6);}',
      /* 🌈 무지개 이름표 (누적 15,000m 해금) */
      '.v46-rainbow{background:linear-gradient(90deg,#f87171,#fbbf24,#34d399,#60a5fa,#a78bfa,#f472b6);',
      '  -webkit-background-clip:text!important;background-clip:text!important;-webkit-text-fill-color:transparent!important;color:transparent!important;',
      '  background-size:200% 100%!important;animation:v46rb 6s linear infinite;}',
      '@keyframes v46rb{0%{background-position:0% 50%}100%{background-position:200% 50%}}',
      '#v46RainbowBtn{margin-left:6px;padding:3px 8px;border-radius:999px;font-size:10px;font-weight:900;cursor:pointer;',
      '  background:linear-gradient(90deg,#f87171,#fbbf24,#34d399,#60a5fa,#a78bfa);color:#0b1024;border:1px solid rgba(255,255,255,.5);}',
      '#v46RainbowBtn.off{background:rgba(255,255,255,.08);color:#94a3b8;border-color:rgba(148,163,184,.4);}',
