          ctx.globalAlpha = Math.min(1, k * 2.2);
          ctx.font = 'bold 24px sans-serif';
          ctx.textAlign = 'center';
          ctx.fillText(e2.e, (pr.rx !== undefined ? pr.rx : pr.x) + 14, (pr.ry !== undefined ? pr.ry : pr.y) - camY - 34 - (1 - k) * 10);
