    try { V.toast('🎲 팀 섞기!', 'lucky', '팀·주자 순서를 새로 짰습니다 (' + keys.length + '명)', 2000); } catch (e) {}
    try { V.beep(880, 0.08, 0.11, 'square', 1320); } catch (e) {}
