    var inPlay = document.body.classList.contains('v47-play');
    hud.style.display = inPlay ? 'grid' : 'none';
    var sh = $('hudShieldMobile');
    var n = 0;
    if (sh) { var mt = /x(\d+)/.exec(sh.textContent || ''); n = mt ? Number(mt[1]) : 0; }
    if (sh) sh.style.display = n > 0 ? 'inline-block' : 'none';
    var hearts = $('hudHearts');
    if (hearts) hearts.style.display = hearts.children.length ? 'flex' : 'none';
