    lava: { k: 'lava', emo: '🌋', t: '용암에 삼켜졌다!', b: '🌋 용암' },
    dive: { k: 'dive', emo: '🌊', t: '숨이 차올랐다!', b: '🌊 산소 부족' },
    timeup: { k: 'time', emo: '⏱️', t: '시간이 다 됐다!', b: '⏱️ 타임오버' },
