    h += row('🌀 태초 확률', [['0', '0%'], ['3', '3%'], ['10', '10%'], ['25', '25%'], ['50', '50%']], String(r.originPct || 0), 'originPct');
    h += row('🎲 랜덤 이벤트', [['1', 'ON'], ['0', 'OFF']], r.events ? '1' : '0', 'events');
    h += row('✨ 아이템', [['1', 'ON'], ['0', 'OFF']], r.items ? '1' : '0', 'items');
