    h += row('🧊 물리', [['basic', '기본'], ['lowgrav', '저중력'], ['fast', '1.5배속'], ['ice', '빙판']], String(x.phys || 'basic'), 'phys');
    h += row('🎯 목표 층수', [['30', '30층'], ['50', '50층'], ['88', '88층'], ['120', '120층']], String(x.tgt || 88), 'tgt');
    h += row('🤖 빈자리 봇', [['0', '없음'], ['1', '1명'], ['2', '2명'], ['3', '3명']], String(x.bots || 0), 'bots');
