      '  white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}',
      '#v48mgTop .tt small{display:block;font-size:10px;color:#8fa3c4;font-family:-apple-system,system-ui,sans-serif;}',
      '.v48mg-b{display:inline-flex;align-items:center;justify-content:center;gap:4px;height:34px;padding:0 11px;',
      '  border-radius:11px;border:1px solid rgba(160,190,235,.26);background:rgba(255,255,255,.06);',
