          var tipX = 268, tipY = 250;
          g.strokeStyle = '#e2e8f0'; g.lineWidth = 2.5;
          g.beginPath(); g.moveTo(196, 372); g.lineTo(tipX, tipY); g.stroke();
          var lineY = S.phase === 'reel' ? 210 : 300;
          g.strokeStyle = 'rgba(226,232,240,.55)'; g.lineWidth = 1;
          g.beginPath(); g.moveTo(tipX, tipY); g.lineTo(tipX + 6, lineY); g.stroke();
          A.circle(g, tipX + 6, lineY, 4, '#f43f5e');
