      '#v48ju .row .nm small{display:block;font-size:11px;color:#9fb3d2;font-weight:800;margin-top:2px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;}',
      '#v48ju .row{padding:9px 10px;min-height:52px;}',
