      ctx.strokeStyle = col; ctx.lineWidth = 2;
      ctx.beginPath(); ctx.arc(pt.x, sy, 12, 0, 6.2832); ctx.stroke();
      ctx.fillStyle = col;
      ctx.globalAlpha = 0.35;
      ctx.beginPath(); ctx.arc(pt.x, sy + 4, 8, 0, 6.2832); ctx.fill();
      ctx.globalAlpha = 1;
