      if (grad) { grad.addColorStop(0, '#fb7185'); grad.addColorStop(0.5, '#fde047'); grad.addColorStop(1, '#38bdf8'); ctx.fillStyle = grad; }
      else ctx.fillStyle = '#fde047';
