/* 패턴 키 -> 이펙트 종류. 판정/속도/데미지는 건드리지 않고 그리는 것만 바꾼다.
   bullet=탄환, drop=낙하물, zone=바닥 장판, beam=레이저, wave=파도,
   gust=돌풍, grav=중력, pillar=기둥, ring=파동, orbiter=공전 구체,
   homing=유도탄, cage=조이기, clone=분신(보스 스프라이트 재사용), dash=돌진 잔상 */
var PATTERN_FX = {
  spread: 'bullet', ring: 'ring', rain: 'drop', laserV: 'beam', laserH: 'beam',
  dash: 'dash', wave: 'wave', gust: 'gust', grav: 'grav', snipe: 'bullet',
  shuriken: 'bullet', clone: 'clone', pillar: 'pillar', patch: 'zone', bomb: 'drop',
  spin: 'ring', sweep: 'beam', rage: 'ring',
  orbit: 'orbiter', homing: 'homing', tide: 'wave', cage: 'cage'
};

/* 이펙트 그리기: fxKey는 FX의 키, x/y는 중심(px), s는 크기(px), c0/c1은 색.
   beam/ring/wave/gust/grav/pillar/cage/dash는 판정 모양을 유지해야 해서
   기존 drawHz의 도형(직사각형/원/줄)을 그대로 쓰고 색/질감만 바꾸는 방식이므로
   여기서는 탄환형(fx 스프라이트)만 그린다. */
function drawFx(ctx, fxKey, x, y, s, c0, c1) {
  var rows = FX[fxKey];
  if (!rows) return false;
  var pal = { a: c0, b: c1 || c0, w: '#ffffff', k: '#1c1526',
    d: (function (h) { var n = parseInt(h.slice(1), 16);
      var r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
      return '#' + [r, g, b].map(function (v) {
        return ('0' + Math.round(v * 0.5).toString(16)).slice(-2);
      }).join(''); })(c0) };
  var cell = s / 8;
  for (var i = 0; i < 8; i++) {
    for (var j = 0; j < 8; j++) {
      var ch = rows[i][j];
      if (ch === '.') continue;
      ctx.fillStyle = pal[ch] || c0;
      ctx.fillRect(Math.round(x - s / 2 + j * cell), Math.round(y - s / 2 + i * cell), Math.ceil(cell), Math.ceil(cell));
    }
  }
  return true;
}


