  function ci(c, x, y, rad, col) { c.fillStyle = col; c.beginPath(); c.arc(x, y, rad, 0, 6.2832); c.fill(); }
  function el(c, x, y, rx, ry, col) { c.fillStyle = col; c.beginPath(); c.ellipse(x, y, rx, ry, 0, 0, 6.2832); c.fill(); }
  function tr(c, x1, y1, x2, y2, x3, y3, col) {
    c.fillStyle = col; c.beginPath(); c.moveTo(x1, y1); c.lineTo(x2, y2); c.lineTo(x3, y3); c.closePath(); c.fill();
  }
  function eyes(c, y, col, glow, dx) {
    dx = dx || 0;
    r(c, 34 + dx, y, 10, 7, '#0b1024');
    r(c, 52 + dx, y, 10, 7, '#0b1024');
    r(c, 36 + dx, y + 1, 6, 5, glow);
    r(c, 54 + dx, y + 1, 6, 5, glow);
    r(c, 37 + dx, y + 1, 2, 2, '#ffffff');
    r(c, 55 + dx, y + 1, 2, 2, '#ffffff');
  }
  B.art = art;

  /* 1. 구름 대왕 */
  art.cloud = function (c, bx, by, u, s, b) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 76, 34, 8, 'rgba(5,3,10,.25)');
    ci(c, 28, 58, 19, p[0]); ci(c, 70, 60, 17, p[0]);
    ci(c, 48, 50, 26, p[1]); ci(c, 34, 64, 16, p[1]);
    r(c, 20, 62, 56, 16, p[1]);
    ci(c, 42, 42, 12, '#ffffff');
    /* 왕관 */
    r(c, 30, 26, 36, 5, p[3]);
    tr(c, 32, 26, 38, 12, 44, 26, p[3]);
    tr(c, 44, 26, 50, 8, 56, 26, p[3]);
    tr(c, 56, 26, 62, 14, 66, 26, p[3]);
    /* 눈썹 */
    r(c, 32, 46, 13, 3, '#475569'); r(c, 51, 46, 13, 3, '#475569');
    eyes(c, 51, p[2], p[2]);
    r(c, 38, 66, 20, 5, '#334155');
    /* 번개 */
    tr(c, 78, 34, 88, 34, 82, 44, p[3]);
    tr(c, 82, 44, 76, 56, 84, 50, p[3]);
    /* 볼 */
    ci(c, 32, 62, 4, 'rgba(56,189,248,.35)'); ci(c, 64, 62, 4, 'rgba(56,189,248,.35)');
    c.restore();
  };

  /* 2. 슈가 마카롱 킹 */
  art.macaron = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 84, 30, 6, 'rgba(5,3,10,.22)');
    /* 크라운 초콜릿 */
    r(c, 32, 16, 32, 9, '#6b3f1d');
    tr(c, 34, 16, 38, 6, 42, 16, '#8b5a2b');
    tr(c, 44, 16, 48, 3, 52, 16, '#8b5a2b');
    tr(c, 54, 16, 58, 6, 62, 16, '#8b5a2b');
    ci(c, 48, 12, 4, '#fde047');
    /* 위 마카롱 껍질 */
    r(c, 20, 25, 56, 6, p[0]);
    r(c, 18, 28, 60, 14, p[0]);
    r(c, 20, 40, 56, 4, '#e88ab8');
    /* 크림 */
    r(c, 20, 44, 56, 12, p[1]);
    ci(c, 26, 56, 6, p[1]); ci(c, 48, 57, 6, p[1]); ci(c, 70, 56, 6, p[1]);
    /* 아래 껍질 */
    r(c, 18, 56, 60, 16, p[0]);
    r(c, 20, 70, 56, 5, '#e88ab8');
    /* 얼굴 */
    r(c, 32, 31, 9, 6, '#0b1024'); r(c, 55, 31, 9, 6, '#0b1024');
    r(c, 34, 32, 5, 4, p[2]); r(c, 57, 32, 5, 4, p[2]);
    r(c, 41, 47, 14, 4, '#7c3aed');
    r(c, 45, 51, 6, 3, '#f472b6');
    /* 스프링클 */
    ['#fde047', '#7dd3fc', '#a7f3d0'].forEach(function (col, i) {
      r(c, 26 + i * 16, 34 + (i % 2) * 4, 4, 2, col);
    });
    c.restore();
  };

  /* 3. 타워크레인 메카 */
  art.crane = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 88, 30, 5, 'rgba(5,3,10,.25)');
    /* 몸통 격자 */
    r(c, 38, 26, 20, 56, p[0]);
    for (var i = 0; i < 5; i++) {
      r(c, 38, 30 + i * 11, 20, 3, '#b45309');
      tr(c, 38, 30 + i * 11, 58, 41 + i * 11, 38, 41 + i * 11, p[1]);
    }
    /* 붐대 */
    r(c, 8, 18, 74, 6, p[0]);
    r(c, 8, 18, 74, 2, p[1]);
    tr(c, 10, 24, 20, 18, 20, 24, '#b45309');
    /* 후크 */
    r(c, 78, 24, 2, 18, '#cbd5e1');
    r(c, 72, 42, 12, 5, '#94a3b8');
    r(c, 70, 47, 4, 6, '#f87171');
    /* 운전석 */
    r(c, 34, 46, 28, 22, '#fde68a');
    r(c, 38, 50, 12, 9, '#0b1024');
    r(c, 40, 51, 7, 6, p[3]);
    r(c, 52, 52, 6, 5, '#0b1024');
    /* 경광등 */
    ci(c, 48, 14, 4, p[3]);
    /* 하단 경고 줄무늬 */
    r(c, 26, 80, 44, 8, '#334155');
    for (var k = 0; k < 4; k++) r(c, 28 + k * 11, 80, 6, 8, p[3]);
    /* 볼트 */
    ci(c, 38, 24, 2, '#94a3b8'); ci(c, 58, 24, 2, '#94a3b8');
    c.restore();
  };

  /* 4. 코스믹 UFO 커맨더 */
  art.ufo = function (c, bx, by, u, s, b) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    var t = (b && b.ai) ? b.ai.t : 0;
    /* 빔 */
    c.globalAlpha = 0.18 + 0.08 * Math.abs(Math.sin(t * 4));
    tr(c, 34, 62, 62, 62, 48, 96, p[2]);
    c.globalAlpha = 1;
    /* 접시 */
    el(c, 48, 58, 38, 12, p[0]);
    el(c, 48, 54, 38, 9, p[1]);
    el(c, 48, 58, 24, 7, '#64748b');
    /* 돔 */
    el(c, 48, 44, 18, 14, 'rgba(165,243,252,.55)');
    el(c, 48, 46, 12, 9, p[3]);
    ci(c, 48, 46, 4, '#0b1024');
    r(c, 46, 47, 2, 2, '#ffffff');
    /* 안테나 */
    r(c, 47, 22, 2, 12, '#cbd5e1');
    ci(c, 48, 20, 3, p[3]);
    /* 램프 */
    ci(c, 26, 62, 3, '#f87171'); ci(c, 48, 65, 3, '#fde047'); ci(c, 70, 62, 3, '#22d3ee');
    /* 패널 선 */
    r(c, 20, 54, 56, 2, '#e0e7ff');
    c.restore();
  };

  /* 5. 대나무 닌자 쇼군 */
  art.ninja = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 86, 26, 5, 'rgba(5,3,10,.3)');
    /* 다리 */
    r(c, 38, 70, 8, 16, '#1e293b'); r(c, 52, 70, 8, 16, '#1e293b');
    /* 몸통 */
    r(c, 32, 40, 32, 34, p[0]);
    r(c, 36, 40, 4, 34, p[1]);
    /* 어깨 갑주 */
    r(c, 26, 38, 12, 10, '#1e293b'); r(c, 58, 38, 12, 10, '#1e293b');
    /* 머리 */
    r(c, 34, 22, 28, 22, '#0f172a');
    r(c, 32, 34, 32, 6, '#1e293b');
    /* 눈 */
    r(c, 38, 30, 8, 4, p[3]); r(c, 52, 30, 8, 4, p[3]);
    r(c, 40, 31, 3, 2, '#0b1024'); r(c, 54, 31, 3, 2, '#0b1024');
    /* 스카프 */
    r(c, 30, 40, 18, 6, p[2]);
    tr(c, 18, 40, 32, 44, 16, 58, p[2]);
    /* 카타나 */
    c.save(); c.translate(70, 62); c.rotate(-0.6);
    r(c, 0, -2, 34, 3, '#e2e8f0'); r(c, 0, -3, 10, 5, '#0f172a');
    c.restore();
    /* 표창 */
    [0, 1].forEach(function (i) {
      var x = 20 + i * 56, y = 56 + i * 6;
      tr(c, x, y - 7, x + 3, y, x, y + 7, '#94a3b8');
      tr(c, x, y - 7, x - 3, y, x, y + 7, '#94a3b8');
      ci(c, x, y, 2, '#0f172a');
    });
    c.restore();
  };

  /* 6. 심해 트라이던트 왕 */
  art.trident = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 88, 28, 5, 'rgba(5,3,10,.3)');
    /* 몸통 */
    r(c, 32, 42, 32, 38, p[0]);
    r(c, 36, 46, 6, 32, p[1]);
    /* 지느러미 */
    tr(c, 32, 46, 16, 60, 30, 66, p[1]);
    tr(c, 64, 46, 80, 60, 66, 66, p[1]);
    /* 머리 */
    r(c, 34, 24, 28, 22, p[1]);
    /* 산호 왕관 */
    [36, 46, 56].forEach(function (x, i) {
      tr(c, x, 24, x + 4, 10 + (i % 2) * 4, x + 8, 24, p[2]);
    });
    /* 눈 */
    r(c, 38, 32, 8, 6, '#0b1024'); r(c, 52, 32, 8, 6, '#0b1024');
    r(c, 40, 33, 4, 4, '#e0f2fe'); r(c, 54, 33, 4, 4, '#e0f2fe');
    /* 수염 거품 */
    ci(c, 42, 50, 4, p[3]); ci(c, 54, 50, 4, p[3]); ci(c, 48, 58, 3, p[3]);
    /* 삼지창 */
    r(c, 82, 22, 3, 60, '#cbd5e1');
    r(c, 76, 18, 15, 3, p[2]); r(c, 76, 26, 15, 3, p[2]);
    tr(c, 78, 18, 82, 8, 86, 18, p[2]);
    /* 비늘 */
    for (var i = 0; i < 3; i++) ci(c, 42 + i * 8, 62 + (i % 2) * 4, 2, 'rgba(165,243,252,.5)');
    c.restore();
  };

  /* 7. 글리치 마스터 */
  art.arcade = function (c, bx, by, u, s, b) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    var t = (b && b.ai) ? b.ai.t : 0;
    el(c, 48, 88, 26, 5, 'rgba(5,3,10,.3)');
    /* 캐비닛 */
    r(c, 26, 18, 44, 68, p[0]);
    r(c, 26, 18, 44, 4, p[1]);
    r(c, 30, 24, 36, 34, '#0b1024');
    r(c, 32, 26, 32, 30, '#161a2e');
    /* 픽셀 얼굴 */
    r(c, 38, 32, 7, 7, p[2]); r(c, 52, 32, 7, 7, p[2]);
    r(c, 40, 34, 3, 3, '#0b1024'); r(c, 54, 34, 3, 3, '#0b1024');
    r(c, 40, 46, 16, 3, p[1]);
    r(c, 44, 49, 3, 3, p[1]); r(c, 50, 49, 3, 3, p[1]);
    /* 글리치 바 */
    if (Math.sin(t * 6) > 0.2) {
      r(c, 33, 36 + ((t * 40) % 16), 30, 2, p[1]);
      r(c, 30, 40 + ((t * 27) % 14), 6, 2, p[2]);
    }
    /* 조이스틱 · 버튼 */
    r(c, 36, 62, 3, 10, '#cbd5e1'); ci(c, 37, 60, 5, p[3]);
    ci(c, 54, 66, 4, '#f87171'); ci(c, 62, 66, 4, '#22d3ee');
    r(c, 26, 80, 44, 6, p[1]);
    c.restore();
  };

  /* 8. 프로스트 자이언트 */
  art.frost = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 88, 30, 5, 'rgba(5,3,10,.25)');
    /* 몸통 */
    r(c, 30, 38, 36, 46, p[0]);
    r(c, 34, 42, 8, 38, p[1]);
    /* 어깨 얼음 */
    tr(c, 30, 40, 18, 24, 32, 22, p[3]);
    tr(c, 66, 40, 78, 24, 64, 22, p[3]);
    tr(c, 42, 36, 48, 18, 54, 36, p[1]);
    /* 머리 */
    r(c, 32, 20, 32, 24, p[1]);
    tr(c, 32, 20, 40, 6, 48, 20, p[3]);
    tr(c, 48, 20, 56, 8, 64, 20, p[3]);
    /* 눈·입 */
    r(c, 38, 30, 8, 5, '#0b1024'); r(c, 52, 30, 8, 5, '#0b1024');
    r(c, 40, 31, 4, 3, p[2]); r(c, 54, 31, 4, 3, p[2]);
    r(c, 38, 40, 22, 4, '#0b1024');
    for (var i = 0; i < 4; i++) r(c, 39 + i * 5, 40, 2, 5, p[1]);
    /* 다리 */
    r(c, 34, 84, 10, 8, p[0]); r(c, 54, 84, 10, 8, p[0]);
    /* 눈송이 */
    ci(c, 70, 66, 3, p[3]); ci(c, 26, 60, 2, p[3]);
    c.restore();
  };

  /* 9. 팬텀 카운트 */
  art.ghost = function (c, bx, by, u, s, b) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    var t = (b && b.ai) ? b.ai.t : 0;
    c.globalAlpha = 0.88;
    /* 꼬리 */
    ci(c, 48, 60, 26, p[0]);
    ci(c, 28, 74, 10, p[0]); ci(c, 48, 80, 9, p[0]); ci(c, 68, 74, 10, p[0]);
    r(c, 24, 50, 48, 18, p[0]);
    /* 얼굴 */
    ci(c, 48, 44, 22, p[0]);
    c.globalAlpha = 1;
    /* 중절모 */
    r(c, 32, 14, 32, 6, '#0b1024');
    r(c, 38, 2, 20, 14, '#0b1024');
    r(c, 38, 12, 20, 3, p[2]);
    /* 눈 */
    r(c, 38, 38, 8, 9, '#0b1024'); r(c, 52, 38, 8, 9, '#0b1024');
    ci(c, 42, 42, 2, p[3]); ci(c, 56, 42, 2, p[3]);
    r(c, 43, 52, 10, 3, '#0b1024');
    /* 촛불 */
    r(c, 74, 52, 5, 16, '#fff1e6');
    ci(c, 76, 48, 4 + Math.sin(t * 8) * 0.6, p[3]);
    ci(c, 76, 47, 2, '#ffffff');
    c.restore();
  };

  /* 10. 마그마 렉스 */
  art.dino = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 46, 88, 32, 5, 'rgba(5,3,10,.3)');
    /* 몸통 */
    el(c, 44, 56, 28, 22, p[0]);
    /* 꼬리 */
    tr(c, 20, 52, 4, 40, 26, 68, p[0]);
    /* 등 가시 */
    [0, 1, 2, 3].forEach(function (i) {
      tr(c, 34 + i * 8, 36, 38 + i * 8, 24 - (i % 2) * 4, 42 + i * 8, 36, p[1]);
    });
    /* 머리 */
    r(c, 44, 24, 40, 28, p[0]);
    r(c, 44, 22, 32, 6, p[1]);
    /* 입 */
    r(c, 50, 44, 34, 9, p[1]);
    for (var i = 0; i < 5; i++) tr(c, 52 + i * 7, 44, 55 + i * 7, 50, 58 + i * 7, 44, '#ffffff');
    /* 눈 */
    r(c, 68, 30, 10, 7, '#0b1024'); r(c, 70, 31, 6, 5, p[2]);
    /* 콧구멍 */
    r(c, 80, 36, 3, 3, p[1]);
    /* 용암 균열 */
    r(c, 34, 58, 12, 3, p[2]); r(c, 44, 66, 10, 3, p[2]); r(c, 56, 58, 8, 3, p[2]);
    /* 팔 */
    r(c, 62, 60, 12, 6, p[0]); r(c, 70, 64, 6, 4, p[1]);
    /* 다리 */
    r(c, 34, 74, 10, 14, p[0]); r(c, 54, 74, 10, 14, p[0]);
    c.restore();
  };

  /* 11. 숙제 괴물 빨간펜 */
  art.school = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 88, 28, 5, 'rgba(5,3,10,.3)');
    /* 종이 날개 */
    tr(c, 24, 40, 6, 30, 8, 60, '#f8fafc');
    tr(c, 72, 40, 90, 30, 88, 60, '#f8fafc');
    /* 칠판 몸통 */
    r(c, 24, 24, 48, 56, '#0f172a');
    r(c, 27, 27, 42, 50, p[0]);
    r(c, 24, 24, 48, 4, p[1]); r(c, 24, 76, 48, 4, p[1]);
    /* 낙서 */
    c.globalAlpha = 0.5;
    r(c, 30, 34, 18, 1, p[1]); r(c, 30, 38, 26, 1, p[1]); r(c, 30, 68, 30, 1, p[1]);
    c.globalAlpha = 1;
    /* X 눈 */
    c.strokeStyle = p[2]; c.lineWidth = 3;
    [38, 56].forEach(function (x) {
      c.beginPath(); c.moveTo(x - 5, 42); c.lineTo(x + 5, 52);
      c.moveTo(x + 5, 42); c.lineTo(x - 5, 52); c.stroke();
    });
    r(c, 38, 60, 20, 3, p[2]);
    /* 빨간펜 팔 */
    r(c, 12, 44, 12, 5, p[2]); r(c, 72, 44, 12, 5, p[2]);
    tr(c, 8, 44, 4, 47, 8, 50, '#fca5a5');
    tr(c, 88, 44, 92, 47, 88, 50, '#fca5a5');
    /* 눈금 */
    r(c, 34, 66, 28, 6, p[1]);
    c.restore();
  };

  /* 12. 크로노 기어 */
  art.clock = function (c, bx, by, u, s, b) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    var t = (b && b.ai) ? b.ai.t : 0;
    el(c, 48, 88, 28, 5, 'rgba(5,3,10,.3)');
    /* 톱니 */
    for (var i = 0; i < 12; i++) {
      var a = (i / 12) * 6.2832;
      c.save(); c.translate(48 + Math.cos(a) * 30, 50 + Math.sin(a) * 30); c.rotate(a);
      r(c, -4, -4, 8, 8, p[2]);
      c.restore();
    }
    ci(c, 48, 50, 30, p[0]);
    ci(c, 48, 50, 24, p[1]);
    /* 시계판 */
    ci(c, 48, 50, 20, '#fef9e7');
    for (var k = 0; k < 12; k++) {
      var ang = (k / 12) * 6.2832;
      r(c, 48 + Math.cos(ang) * 16 - 1, 50 + Math.sin(ang) * 16 - 1, 2, 2, '#78350f');
    }
    /* 바늘 */
    c.save(); c.translate(48, 50); c.rotate(t * 1.4);
    r(c, -2, -14, 4, 16, '#78350f');
    c.rotate(-t * 3.6);
    r(c, -1, -20, 2, 10, '#b91c1c');
    c.restore();
    ci(c, 48, 50, 3, p[0]);
    /* 진자 */
    r(c, 46, 78, 3, 12, p[2]);
    ci(c, 47, 88, 5, p[2]);
    /* 눈 */
    ci(c, 41, 44, 3, '#0b1024'); ci(c, 55, 44, 3, '#0b1024');
    /* 태엽 열쇠 */
    r(c, 76, 28, 3, 12, '#94a3b8');
    ci(c, 77, 26, 5, '#94a3b8'); ci(c, 77, 26, 2, '#475569');
    c.restore();
  };

  /* 13. 토스터 타이탄 */
  art.toaster = function (c, bx, by, u, s) {
    c.save(); c.translate(bx, by); c.scale(u, u);
    var p = s.c;
    el(c, 48, 88, 30, 5, 'rgba(5,3,10,.3)');
    /* 빵 날개 */
    tr(c, 26, 30, 10, 16, 26, 12, '#fde68a');
    tr(c, 70, 30, 86, 16, 70, 12, '#fde68a');
    r(c, 12, 16, 16, 18, '#fde68a'); r(c, 68, 16, 16, 18, '#fde68a');
    r(c, 14, 16, 12, 4, '#f59e0b'); r(c, 70, 16, 12, 4, '#f59e0b');
    /* 몸통 */
    r(c, 24, 32, 48, 46, p[0]);
    r(c, 28, 36, 40, 8, '#64748b');
    r(c, 26, 32, 44, 4, p[1]);
    r(c, 24, 74, 48, 4, '#64748b');
    /* 슬롯 · 토스트 */
    r(c, 32, 28, 32, 4, '#334155');
    /* 얼굴 */
    r(c, 34, 48, 10, 7, '#0b1024'); r(c, 52, 48, 10, 7, '#0b1024');
    r(c, 36, 49, 6, 4, p[2]); r(c, 54, 49, 6, 4, p[2]);
    r(c, 42, 60, 12, 3, '#334155');
    /* 다이얼 */
    ci(c, 36, 68, 5, '#475569'); r(c, 35, 64, 2, 5, '#fde047');
    ci(c, 58, 68, 4, p[2]);
    /* 스파크 */
    tr(c, 78, 44, 84, 40, 82, 50, '#fde047');
    tr(c, 14, 46, 8, 42, 10, 52, '#fde047');
    c.restore();
  };

