      var md = (root.JWMode && root.JWMode.lastSoloEnd) || {};
      var mid = String(md.modeId || md.mode || '');
      if (mid !== 'bossrush' && mid !== 'raid') return;
      var b = (V.G && V.G.boss) || null;
