        '<div class="tx"><div class="mn">' + esc(mapName(id)) + (id === cur ? ' · 지금 맵' : '') + '</div>' +
        '<div class="bn">' + esc(s2.e || '👑') + ' ' + esc(s2.n) + '</div>' +
        '<div class="q">' + esc(s2.t || '') + '</div>' +
        '<div class="pt">' + s2.pats.map(function (p) { return esc(p[1]); }).join(' · ') + ' · HP ' + (s2.hp || 140) + '</div></div></div>';
