/* ==========================================================================
   v5.0-easy : '쉬움' 난이도 정식 등록 + 필터 도우미 + 맵 카드 라벨 보강
   - 난이도 5단계: 쉬움 / 보통 / 어려움 / 극악 (+ 기존 '기본')
   - 맵 선택 · 방 설정 · 제안하기 · 랭킹 필터가 모두 이 도우미를 쓴다
   ========================================================================== */
(function (root) {
  'use strict';
  var V = root.JW43;
  if (!V) return;
  if (root.JW50DIFF) return;

  var ORDER = { '쉬움': 1, '기본': 2, '보통': 2, '어려움': 3, '극악': 4 };
  var COLOR = { '쉬움': '#86efac', '기본': '#93c5fd', '보통': '#93c5fd', '어려움': '#fca5a5', '극악': '#f87171' };

  function diffOf(id) {
    var d = '';
    try { var m = root.JWMap && root.JWMap.byId ? root.JWMap.byId(id) : null; d = (m && m.diff) || ''; } catch (e) {}
    return d || '기본';
  }
  function isEasy(id) { return diffOf(id) === '쉬움'; }
  function rank(id) { return ORDER[diffOf(id)] || 2; }
  function color(id) { return COLOR[diffOf(id)] || '#93c5fd'; }

  root.JW50DIFF = { diffOf: diffOf, isEasy: isEasy, rank: rank, color: color, ORDER: ORDER };
  /* 여러 모듈(클로저)에서 공통으로 쓰는 전역 술어 */
  window.__jw50easy = function (id) { return diffOf(id) === '쉬움'; };

  /* 45맵 카운터를 타이틀/로비 문구에도 반영 */
  function mapCount() {
    try { return (root.JWMap && root.JWMap.list) ? root.JWMap.list.length : 0; } catch (e) { return 0; }
  }
  root.JW50DIFF.count = mapCount;

  /* 난이도 배지가 '쉬움'이면 색을 초록으로 (맵 카드가 diffColor 를 쓰지 않는 곳 보완) */
  function tintEasy() {
    try {
      var list = root.JWMap && root.JWMap.list;
      if (!list) return;
      list.forEach(function (m) {
        if (!m) return;
        if (m.diff === '쉬움' && m.diffColor !== '#86efac') m.diffColor = '#86efac';
        if (!m.diffColor) m.diffColor = COLOR[m.diff] || '#93c5fd';
      });
    } catch (e) {}
  }
  setTimeout(tintEasy, 200);
  setTimeout(tintEasy, 1200);
  console.log('[JW50] difficulty ready · maps', mapCount());
})(window);


