  /* ---------- v5.12 H안 : 발판 종류 색 = 맵 팔레트 파생 ----------
     축은 둘 — 밝기, 따뜻함/차가움. 색은 '종류 + 맵 팔레트'로만 정하고 seed·시간과
     무관하다(paint() 캐시 안전). 모양(실루엣·무늬)은 건드리지 않고 색만 교체한다. */
  function chex(c) {
    var o = (typeof c === 'string') ? hx(c) : { r: c.r, g: c.g, b: c.b };
    var s = '#';
    [o.r, o.g, o.b].forEach(function (v) {
      var n = Math.max(0, Math.min(255, Math.round(v)));
      s += (n < 16 ? '0' : '') + n.toString(16);
    });
    return s;
  }
  function clue(c, k) { c = chex(c); return chex(k > 0 ? mix(c, '#ffffff', k) : mix(c, '#05070c', -k)); }
  function csat(c, k) {
    var o = (typeof c === 'string') ? hx(c) : c, m = (o.r + o.g + o.b) / 3;
    return chex({ r: m + (o.r - m) * (1 + k), g: m + (o.g - m) * (1 + k), b: m + (o.b - m) * (1 + k) });
  }
  function clum(c) {
    var o = (typeof c === 'string') ? hx(c) : c;
    return (0.299 * o.r + 0.587 * o.g + 0.114 * o.b) / 255;
  }
