      c.fillStyle = rgb(rk);
      c.beginPath(); c.moveTo(w / 2, hh / 2 - 8); c.lineTo(w / 2 + 3, hh / 2 - 4); c.lineTo(w / 2 - 3, hh / 2 - 4); c.closePath(); c.fill();
      c.restore();
