/* ===== v59 inline block #75 (was index.html L68254-68381) ===== */

/* ==========================================================================
   v5.1-perf : 전체 최적화 — 프레임·메모리·DOM·타이머
   - 타이틀(대기) 화면에서는 게임 캔버스 프레임을 20fps 로 제한 (배터리·발열)
   - 파티클/텍스트 상한 (메모리 누수 방지)
   - HUD/그리드 contain · 썸네일 content-visibility 로 레이아웃 비용 절감
   - 화면이 숨겨지면 무거운 주기 작업 정지
   ========================================================================== */
(function (root) {
  'use strict';
  var V = root.JW43;
  if (!V) return;
  if (root.JW51PERF) return;
  var C = root.JW51U;
  var doc = document;
  var $ = function (id) { return doc.getElementById(id); };

  var ST = { gate: 0, saved: 0, capped: 0, lastFps: 0 };
  var rafOrig = window.requestAnimationFrame ? window.requestAnimationFrame.bind(window) : null;
  var busyUntil = 0;

  function isIdle() {
    try {
      if (doc.hidden) return false;
      if (Date.now() < busyUntil) return false;
      var j = root.__jwg;
      if (!j || !j.game) return false;
      if (j.game.inPlay || j.game.victory) return false;   /* 인게임은 절대 개입하지 않는다 */
      var t = $('titleScreen');
      if (!t || t.classList.contains('hidden')) return false;
      /* 위저드·모달·튜토리얼 열려 있으면 정상 속도 */
      if (!($('v43Wiz') || {}).classList || !$('v43Wiz').classList.contains('hidden')) return false;
      if ($('v51Tut') && !$('v51Tut').classList.contains('hide')) return false;
      var mods = doc.querySelectorAll('.v51m:not(.hide), .v43-modal:not(.hidden), .v44-modal:not(.hidden), #v48rk:not(.hidden)');
      if (mods && mods.length) return false;
      return true;
    } catch (e) { return false; }
  }

  /* rAF 게이트: 대기 화면에서 3프레임 중 1프레임만 통과 (약 20fps) */
  function installGate() {
    if (!rafOrig || window.requestAnimationFrame.__v51) return;
    var n = 0;
    var w = function (cb) {
      if (!isIdle()) return rafOrig(cb);
      n++;
      if (n % 3 === 0) return rafOrig(cb);
      ST.gate++;
      /* 프레임을 '버리지' 않고 살짝 늦춰서 실행한다 (루프가 죽지 않게) */
      return setTimeout(function () { try { rafOrig(cb); } catch (e) {} }, 34);
    };
    w.__v51 = true;
    window.requestAnimationFrame = w;
  }

  /* 파티클·텍스트 상한 */
  function capArrays() {
    var j = root.__jwg;
    if (!j || !j.game) return;
    var g = j.game;
    if (g.particles && g.particles.length > 240) { g.particles.splice(0, g.particles.length - 240); ST.capped += 60; }
    if (g.texts && g.texts.length > 60) { g.texts.splice(0, g.texts.length - 60); }
    if (g.rocks && g.rocks.length > 42) { g.rocks.splice(0, g.rocks.length - 42); }
  }

  /* CSS 최적화 */
  function css() {
    if ($('v51perfCss')) return;
    var s = doc.createElement('style');
    s.id = 'v51perfCss';
    s.textContent = [
      /* HUD·버튼은 자기 영역만 다시 그린다 */
      '#gameHud{contain:layout style paint;}',
      '#v43Root{contain:layout style;}',
      /* 성능: 스크롤 목록만 건너뛰기 (모달·탭 전환은 content-visibility 로 감추지 않는다 —
         숨김/표시를 오갈 때 1프레임 번쩍이는 원인이었다) */
      /* 대기 화면에서 배경 장식 애니메이션 정지 */
      'body.v51idle .v42-world figure,body.v51idle #v42World{animation-play-state:paused!important;}'
    ].join('\n');
    doc.head.appendChild(s);
  }

  function markIdle() {
    var idle = isIdle();
    doc.body.classList.toggle('v51idle', !!idle);
    ST.lastIdle = idle;
  }

  /* 화면 숨김 시 무거운 주기 작업 건너뛰기 (60_common 스케줄러에 적용) */
  function patchScheduler() {
    if (!C || C.__v51hidden) return;
    C.__v51hidden = true;
    var origEvery = C.every;
    C.every = function (name, ms, fn) {
      return origEvery(name, ms, function () {
        if (doc.hidden && /^(specTick|qolRun|qolExtras|titleDecor|trajPractice|dmRows|dmJoin)$/.test(name)) return;
        return fn.apply(this, arguments);
      });
    };
  }

  function bumpBusy(ms) { busyUntil = Date.now() + (ms || 400); }

  function boot() {
    css();
    installGate();
    patchScheduler();
    C.every('perfCap', 500, capArrays);
    C.every('perfIdle', 700, markIdle);
    /* 화면 전환 시 잠깐 게이트 해제 (부드러운 전환) */
    ['click', 'touchstart', 'keydown'].forEach(function (ev) {
      doc.addEventListener(ev, function () { bumpBusy(600); }, { passive: true });
    });
    doc.addEventListener('visibilitychange', function () { bumpBusy(400); });
  }
  if (doc.readyState === 'loading') doc.addEventListener('DOMContentLoaded', function () { setTimeout(boot, 300); });
  else setTimeout(boot, 300);
  setTimeout(boot, 1500);

  root.JW51PERF = {
    state: function () { return { gated: ST.gate, capped: ST.capped, idle: !!ST.lastIdle, room: doc.hidden }; },
    release: function (ms) { bumpBusy(ms || 1500); },
    isIdle: isIdle
  };
  console.log('[JW51PERF] ready');
})(window);


