          return '<button type="button" id="' + it.id + '" class="' + it.cls + '" style="width:100%;padding:11px;font-size:14px">' + esc(it.label) +
            '<span style="display:block;font-size:10.5px;font-weight:700;opacity:.85">' + esc(it.sub) + '</span></button>';
