      if (!!o.big !== big) { big = !!o.big; ctx.font = big ? 'bold 17px "Galmuri11", monospace' : 'bold 13px "Galmuri11", monospace'; }
      var yy = (o.y - camY - Math.min(4, k * 8)) | 0;
      var xx = o.x | 0;
