      g.beginPath();
      g.moveTo(x - 8, my); g.lineTo(x - 15, my - 5); g.lineTo(x - 15, my + 5);
      g.closePath(); g.fill();
      g.globalAlpha = 0.8;
      g.fillRect(x - 4, my - 1.5, 11, 3);
