    Z: { m: [[1, 1, 0], [0, 1, 1], [0, 0, 0]] },
    J: { m: [[1, 0, 0], [1, 1, 1], [0, 0, 0]] },
    L: { m: [[0, 0, 1], [1, 1, 1], [0, 0, 0]] }
