      S.hits = 0; S.rally = 0; S.bestRally = 0; S.smash = 0;
      S.hitPts = 0; S.smashPts = 0; S.pointPts = 0; S.rallyPts = 0;
      S.winBonus = 0; S.timeBonus = 0; S.rallyBonus = 0; S.score = 0;
