      S.ready = false;
      S.time = 0; S.left = LIMIT; S.lastTick = -1;
      refreshColors();
      serve(-1);
      banner('🏓 시작!', '5점 선승 · 60초 타임어택', '#a5f3fc', 1.0, 210);
